WITH long_format AS (SELECT * FROM (SELECT id, store_id, amount, shipping_fee FROM orders) src UNPIVOT (value FOR kpi IN (amount, shipping_fee))) SELECT kpi, CASE WHEN value >= 82 THEN 'HIGH' ELSE 'LOW' END AS value_tier, MAX(value) FILTER (WHERE kpi = 'shipping_fee') AS shipping_fee_max_value, COUNT_IF(kpi = 'shipping_fee') AS shipping_fee_events, ROUND(SUM(value) / NULLIF(COUNT(CASE WHEN kpi = 'amount' THEN 1 END), 0), 2) AS value_per_amount, COUNT(*) FILTER (WHERE kpi = 'shipping_fee') AS shipping_fee_rows, ROUND(SUM(value) / NULLIF(COUNT(CASE WHEN kpi = 'amount' THEN 1 END), 0), 2) AS value_per_amount_2, COUNT(*) AS event_count FROM long_format GROUP BY kpi, CASE WHEN value >= 82 THEN 'HIGH' ELSE 'LOW' END HAVING event_count < 1 ORDER BY shipping_fee_events DESC;
